${pagingTop}
SELECT
	homepage_id, checkinout_survey_idx, checkinout_survey_req_idx, checkinout_survey_answer, member_age,
	member_sex, TO_CHAR(add_date, 'yyyy-mm-dd hh24:mi:ss') as add_date
FROM
	CHECKINOUT_SURVEY_REQ
WHERE 
	homepage_id = #{homepage_id}
AND checkinout_survey_idx = #{checkinout_survey_idx}

AND	${search_type} LIKE '%'||#{search_text}||'%'

ORDER BY checkinout_survey_req_idx
${pagingBottom}

SELECT COUNT(*) FROM CHECKINOUT_SURVEY_REQ WHERE homepage_id = #{homepage_id} AND checkinout_survey_idx = #{checkinout_survey_idx}
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY checkinout_survey_req_idx

mapper.insert:

	SELECT NVL(MAX(checkinout_survey_req_idx),0)+1 FROM CHECKINOUT_SURVEY_REQ WHERE HOMEPAGE_ID = #{homepage_id} AND checkinout_survey_idx = #{checkinout_survey_idx}

INSERT INTO CHECKINOUT_SURVEY_REQ
(
	homepage_id, checkinout_survey_idx, checkinout_survey_req_idx, checkinout_survey_answer, member_age,
	member_sex, add_date
) VALUES (
	#{homepage_id}, #{checkinout_survey_idx}, #{checkinout_survey_req_idx}, #{checkinout_survey_answer}, #{member_age},
	#{member_sex}, SYSDATE
)

mapper.select:
SELECT member_age, member_sex, ( SELECT checkinout_survey_question_title FROM CHECKINOUT_SURVEY_QUESTION WHERE checkinout_survey_question_idx = checkinout_survey_answer AND homepage_id = #{homepage_id}
AND checkinout_survey_idx = #{checkinout_survey_idx}
) AS checkinout_survey_answer, SUM(req_count) AS req_count FROM ( SELECT member_age, member_sex, checkinout_survey_answer, req_count FROM ( SELECT checkinout_survey_req_idx, TO_NUMBER(SUBSTR(member_age, 1, 4)) AS member_age, member_sex, REGEXP_SUBSTR(checkinout_survey_answer, '[^,]+', 1, LEVEL) AS checkinout_survey_answer, 1 AS req_count FROM CHECKINOUT_SURVEY_REQ WHERE homepage_id = #{homepage_id}
AND TO_DATE(add_date,'yyyy-MM-dd') BETWEEN #{start_date} AND #{end_date}
AND checkinout_survey_idx = #{checkinout_survey_idx}
CONNECT BY LEVEL <= LENGTH(REGEXP_REPLACE(checkinout_survey_answer, '[^,]+')) + 1 ) GROUP BY checkinout_survey_req_idx, member_age, member_sex, checkinout_survey_answer ORDER BY checkinout_survey_answer ) GROUP BY member_age, member_sex, checkinout_survey_answer
